"""Localize restart differences in the completed live D1 integration arms."""

import hashlib
import json
from pathlib import Path
import sys

from rich.console import Console
import torch


def leaves(value):
    if torch.is_tensor(value):
        raw = value.detach().reshape(-1).contiguous().view(torch.uint8).numpy()
        return [str(value.dtype), list(value.shape), hashlib.sha256(raw.tobytes()).hexdigest()]
    if isinstance(value, dict):
        return {str(key): leaves(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [leaves(item) for item in value]
    return value


def load(path):
    return torch.load(path, map_location="cpu", weights_only=True)


def mismatches(first, second):
    return sorted(str(key) for key in first.keys() | second.keys()
                  if key not in first or key not in second or leaves(first[key]) != leaves(second[key]))


root, output = map(Path, sys.argv[1:])
record = json.loads((root / "integration.json").read_text())
arms = record["arms"]


def compare(left, right, step):
    a = Path(arms[left]["checkpoint_dir"])
    b = Path(arms[right]["checkpoint_dir"])
    names = [f"model_{step:06d}.pt"]
    names.extend(f"{kind}_{step:06d}_rank{rank}.pt" for kind in ("optim", "train") for rank in (0, 1))
    results = {}
    for file in names:
        before, after = load(a / file), load(b / file)
        if isinstance(before, list):
            results[file] = [mismatches(x, y) for x, y in zip(before, after, strict=True)]
        else:
            results[file] = mismatches(before, after)
            if file.startswith("train_"):
                results[f"{file}:subfields"] = {
                    key: mismatches(before[key], after[key]) for key in results[file]
                    if isinstance(before[key], dict) and isinstance(after[key], dict)
                }
    return results


checks = {
    "same_boundary_live_reference_vs_graph_step2": compare("reference", "graph", 2),
    "uninterrupted_vs_resumed_reference_step4": compare("reference", "resume_reference", 4),
    "uninterrupted_vs_resumed_graph_step4": compare("graph", "resume_graph", 4),
}
result = {
    "checks": checks,
    "final_bpb": {name: arms[name]["short_bpb"] for name in
                  ("reference", "graph", "resume_reference", "resume_graph")},
}
with output.open("x") as stream:
    json.dump(result, stream, indent=2, sort_keys=True, allow_nan=False)
    stream.write("\n")
Console().print_json(data={
    name: {file: len(fields) for file, fields in results.items()} for name, results in checks.items()
})

